def read(p): return open(os.path.join(ROOT, p), encoding='utf-8').read()
def write(p, s): open(os.path.join(ROOT, p), 'w', encoding='utf-8', newline='').write(s)

TPL = read('vyveski.html')
HEAD_END = TPL.index('<title>')
HEADER = TPL[TPL.index('<header class="hdr"'):TPL.index('<main id="top">')]
FOOTER = TPL[TPL.index('<footer class="ftr">'):TPL.index('</footer>') + 9]
MBAR = TPL[TPL.index('<div class="mbar">'):TPL.index('<script src="assets/app.js"')].replace('href="#builder">Расчёт','href="#lead">Расчёт')

def fix_footer(s):
    s = re.sub(r'<div><h5>Услуги</h5><ul(?: class="two")?>.*?</ul></div>', FTR_SVC, s, count=1, flags=re.S)
    s = re.sub(r'<div class="ftr-row">.*?</div>(\s*<div class="ftr-legal">.*?</div>)?', FTR_ROW, s, count=1, flags=re.S)
    return s

def page(slug, title, desc, body, quiz='', scripts=('app', 'quiz')):
    head = (f'<!doctype html>\n<html lang="ru">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>{E(title)}</title>\n'
            f'<meta name="description" content="{E(desc)}">\n<link rel="canonical" href="{DOMAIN}/{slug}">\n<meta property="og:title" content="{E(title)}">\n'
            f'<meta property="og:description" content="{E(desc)}">\n<meta property="og:type" content="website">\n<link rel="icon" href="img/logo-mark.png">\n'
            '<link href="assets/fonts/site.css" rel="stylesheet">\n'
            '<link rel="stylesheet" href="assets/styles.css">\n</head>\n')
    sc = ''.join(f'<script src="assets/{n}.js" defer></script>\n' for n in scripts)
    return head + f'<body{" data-quiz=" + chr(34) + quiz + chr(34) if quiz else ""}>\n\n' + HEADER + '<main id="top">\n' + body + '\n</main>\n\n' + fix_footer(FOOTER) + '\n\n' + MBAR + sc + '</body>\n</html>\n'

def hero(label, h1, lead, scene, cta, cta_href='#lead', quiz='', cta2=('', ''), facts=(), aria=''):
    q = f' data-quiz="{quiz}"' if quiz else ''
    f = ''.join(f'<div class="fact"><b>{b}</b><span>{s}</span></div>' for b, s in facts)
    c2 = f'<a class="btn btn-line" href="{cta2[1]}">{cta2[0]}</a>' if cta2[0] else ''
    return (f'<!-- HERO -->\n<section class="hero hero-dk">\n  <div class="wrap hero-grid">\n    <div>\n      <span class="label reveal"><i class="sq"></i>{label}</span>\n'
            f'      <h1 class="reveal d1">{h1}</h1>\n      <p class="lead reveal d2">{lead}</p>\n      <div class="hero-cta reveal d3"><a class="btn btn-ink" href="{cta_href}"{q}>{cta} {ARROW}</a>{c2}</div>\n'
            + (f'      <div class="facts reveal d4">{f}</div>\n' if facts else '') +
            f'    </div>\n    <div class="tscene reveal d2" data-scene="{scene}" aria-label="{E(aria or "Тигр Рикс+С за работой")}"></div>\n  </div>\n</section>\n')

