def svc_page(slug, title, desc, label, h1, lead, scene, quiz, facts, cards, albums, steps, faq, lead_title, opts, note=''):
    cards_html = ''.join(f'<a href="#lead" data-quiz="{quiz}" class="s-card"><span class="no">{i + 1:02d}</span><h3>{t}</h3><p>{d}</p><div class="pr"><span>{p}</span><span class="go">→</span></div></a>' for i, (t, d, p) in enumerate(cards))
    works = (f'''<section class="sec white" id="works"><div class="wrap"><div class="sec-head"><div><span class="label reveal"><i class="sq"></i>Наши работы</span><h2 class="h2 reveal d1">Что мы уже сделали</h2></div>
      <p class="lead reveal d2" style="max-width:420px">Нажмите на фото, чтобы рассмотреть. Больше — в <a href="raboty.html" style="color:inherit;text-decoration:underline">галерее</a>.</p></div>
    <div class="vk-strip reveal d2" data-albums="{albums}" data-limit="10"></div></div></section>''' if albums else '')
    steps_html = ''.join(f'<div class="step reveal d{i}"><span class="n">{i + 1:02d} —</span><h4>{t}</h4><p>{d}</p></div>' for i, (t, d) in enumerate(steps))
    faq_html = ''.join(f'<details class="faq-i reveal"><summary>{q}</summary><p>{a}</p></details>' for q, a in faq)
    body = (hero(label, h1, lead, scene, 'Рассчитать за 1 минуту', quiz=quiz, cta2=('Что делаем', '#types'), facts=facts) +
            f'''
<section class="sec" id="types"><div class="wrap"><div class="sec-head"><div><span class="label reveal"><i class="sq"></i>01 / Что делаем</span><h2 class="h2 reveal d1">{E(title.split(' в Йошкар')[0].split(' —')[0])}</h2></div>
  <p class="lead reveal d2" style="max-width:440px">{note or 'Дизайн, изготовление и монтаж — под одной крышей. Цена — после макета и выбора материалов, без доплат по ходу.'}</p></div>
  <div class="svc reveal">{cards_html}</div></div></section>
{works}
<section class="sec dark"><div class="wrap"><span class="label reveal"><i class="sq"></i>02 / Как работаем</span><h2 class="h2 reveal d1">Четыре шага</h2><div class="steps">{steps_html}</div></div></section>
<section class="sec" id="faq"><div class="wrap"><span class="label reveal"><i class="sq"></i>03 / Вопросы</span><h2 class="h2 reveal d1">Частые вопросы</h2><div class="faq">{faq_html}</div></div></section>
''' + LEAD_FORM(lead_title, 'Ответьте на пару вопросов — менеджер придёт к разговору подготовленным и пришлёт расчёт.', ['Расчёт в день обращения', 'Дизайн в вашем стиле', 'Работаем с 1995 года'], opts))
    write(slug, page(slug, title, desc, body, quiz, ('app', 'quiz', 'gallery', 'scenes')))

