def doc_page(slug, title, h1, desc, sections, intro=''):
    toc = ''.join(f'<li><a href="#s{i + 1}">{E(t)}</a></li>' for i, (t, _) in enumerate(sections))
    secs = ''.join(f'<section id="s{i + 1}"><h2>{i + 1}. {E(t)}</h2>{c}</section>' for i, (t, c) in enumerate(sections))
    body = (f'<section class="doc-hero"><div class="wrap"><span class="label"><i class="sq"></i>Документы</span><h1>{h1}</h1><p class="doc-meta">Редакция от {LEGAL_DATE} · Оператор: {CO["short"]}, ИНН {CO["inn"]}</p>{intro}</div></section>'
            f'<section class="sec doc"><div class="wrap doc-grid"><aside class="doc-toc"><b>Содержание</b><ol>{toc}</ol>'
            f'<div class="doc-links"><a href="privacy.html">Политика ПДн</a><a href="soglasie.html">Согласие на обработку ПДн</a><a href="cookies.html">Политика cookie</a><a href="pravovaya-informaciya.html">Правовая информация</a></div></aside>'
            f'<article class="doc-body">{secs}</article></div></section>')
    write(slug, page(slug, title, desc, body, '', ('app',)))

