    if f in SCENE_OF and 'class="tscene' not in s:
        a = s.index('<!-- HERO -->'); b = s.index('</section>', a) + len('</section>')
        h = s[a:b]
        if 'hero-grid' in h:
            ls = h.index('<div class="wrap hero-grid">'); left_end = h.index('\n    </div>\n', ls) + len('\n    </div>\n')
            end = h.rindex('  </div>\n</section>')
            h = h[:left_end] + f'    <div class="tscene reveal d2" data-scene="{SCENE_OF[f]}"></div>\n' + h[end:]
        else:  # простой первый экран без сетки — заворачиваем в сетку
            ws = h.index('<div class="wrap">'); we = h.rindex('  </div>\n</section>')
            inner = h[ws + len('<div class="wrap">'):we]
            h = h[:ws] + '<div class="wrap hero-grid">\n    <div>' + inner + '    </div>\n    <div class="tscene reveal d2" data-scene="' + SCENE_OF[f] + '"></div>\n' + h[we:]
            h = re.sub(r'<section class="hero"[^>]*>', '<section class="hero hero-dk">', h, count=1)
        h = h.replace('<section class="hero">', '<section class="hero hero-dk">', 1)
        s = s[:a] + h + s[b:]
    if 'class="tscene' in s and 'assets/scenes.js' not in s:
        s = s.replace('</body>', '<script src="assets/scenes.js" defer></script>\n</body>', 1)
    write(f, s)

